    def are_parallel(slope1, slope2):
        return slope1 == slope2

    def are_intersecting(p1, p2, p3, p4):
        slope1 = get_slope(p1, p2)
        slope2 = get_slope(p3, p4)
        if are_parallel(slope1, slope2):
            return False
        return True

    count = 0
    for p1, p2, p3, p4 in combinations(poles, 4):
        if are_intersecting(p1, p2, p3, p4):
            count += 1
    return count

