def count_intersections(n, points):
    def slope(p1, p2):
        return float('inf') if p1[0] == p2[0] else (p1[1] - p2[1]) / (p1[0] - p2[0])

    def are_intersecting(line1, line2):
        s1 = slope(*line1)
        s2 = slope(*line2)
        if s1 == s2:
            return False
        p1, p2 = line1
        q1, q2 = line2
        return not ((p1 == q1 or p1 == q2) or (p2 == q1 or p2 == q2))

    intersections = 0
    for line1, line2 in combinations(points, 2):
        if are_intersecting(line1, line2):
            intersections += 1
    return intersections

